import { useEffect } from 'react';
import { useInView } from 'react-intersection-observer';
import { EmptyList } from '~/widgets/empty-list';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useIssuedVoucherListInfiniteQuery } from '~/entities/voucher/api/hooks/use-issued-voucher-list-infinite-query';
import { VOUCHER_LIST_PAGING } from '~/entities/voucher/model/constants';
import { VoucherItem } from '~/entities/voucher/ui/voucher-item';
import { VoucherType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

type VoucherContentProps = {
  aliasNm: string;
};

export const VoucherContent = ({ aliasNm }: VoucherContentProps) => {
  const [ref, isContentVisible] = useInView();
  const { data: userRes } = useGetUserInfoQuery();
  const cstmrNo = userRes?.tbCstmrMastr?.cstmrNo ?? '';
  const userAliasNm = userRes?.tbCstmrMastr?.aliasNm ?? '';
  const {
    data: myVoucher,
    fetchNextPage,
    hasNextPage,
    refetch,
  } = useIssuedVoucherListInfiniteQuery({
    paging: {
      ...VOUCHER_LIST_PAGING,
      orderBy: {
        columnList: [
          /* 상태코드
           ST0501:사용,
           ST0502:사용중지,
           ST0503:폐기,
           ST0504:기간만료
          */
          { columnName: 'vouchProcSttusCd', sortDirection: 'ASC' },
          // 바우처 사용시작일 최근 순
          { columnName: 'rcvfverUseStartDt', sortDirection: 'DESC' },
          // 잔액 큰 순
          // { columnName: 'pymntAmt', sortDirection: 'DESC' },
          // 이름 순
          { columnName: 'vouchNm', sortDirection: 'DESC' },
        ],
        toSnakeCase: true,
      },
    },
    aliasNm,
    cstmrNo,
    userAliasNm,
  });
  const myVoucherResult = myVoucher?.pages?.[0]?.result;
  const voucherListByWallet = (myVoucherResult?.walletList ?? []).flatMap((walletItem) => walletItem.list ?? []);
  const myVoucherList =
    aliasNm === 'ALL'
      ? voucherListByWallet.length > 0
        ? voucherListByWallet
        : (myVoucherResult?.list ?? []).flat()
      : (myVoucherResult?.list ?? []).flat();

  useEffect(() => {
    if (hasNextPage && isContentVisible) fetchNextPage();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [aliasNm, cstmrNo, userAliasNm, hasNextPage, isContentVisible]);

  if (!myVoucher || myVoucherList.length === 0) {
    return <EmptyList message={i18n.t('validation:noVouchersAvailable')} reset={refetch} />;
  }

  return (
    <div className="vouc-list">
      <ul>
        {myVoucherList.map((item, index) => (
          <li key={index} ref={index + 1 === myVoucherList.length ? ref : null}>
            <VoucherItem item={{ ...item, type: VoucherType.내_바우처 }} />
          </li>
        ))}
      </ul>
    </div>
  );
};
